刚学c语言写了一下#include&lt;stdio.h&gt;
#include&lt;math.h&gt;

int main(void)
{
	double i = 1;
	double u = i*i;
	int j = 1;
	int c = 0;
	printf(&quot;输入精度1~7:\n&quot;);
	scanf(&quot;%d&quot;,&amp;c);
	for(j=1;j&lt;c;j++)
	{
		while(u&lt;2)
		{
			i+=pow(0.1,j);
			u = i*i;
			//printf(&quot;%le\n&quot;,i);
		}
		while(u&gt;2)
		{
			i-=pow(0.1,j);
			u = i*i;
			printf(&quot;%le\n&quot;,i);
		}
	}
return 0;
}
